TITLE = "Admission Bachelor 1 Cybersécurité 2026"
DESC = "QCM d'admission B1 Cyber (proposition de Dylan, v2, relue). 55 questions dont 5 énigmes CYBEROKU, 55 minutes, 1 point par question ; questions à plusieurs réponses : tout ou rien. Aucun prérequis technique : logique, raisonnement pas à pas et bons réflexes numériques. Seuil d'admissibilité proposé : 28/55 (50 %)."
Q = [
("Quel nombre complète la suite : 2, 6, 12, 20, 30, … ?", ["42","40","44","36"], "A", "Logique & raisonnement", "Les écarts augmentent de 2 à chaque fois : +4, +6, +8, +10, puis +12. 30 + 12 = 42."),
("Quel nombre complète la suite : 3, 9, 27, 81, … ?", ["243","324","162","108"], "A", "Logique & raisonnement", "Chaque nombre est multiplié par 3 : 81 × 3 = 243."),
("Quel nombre complète la suite : 5, 10, 20, 40, … ?", ["50","80","45","60"], "B", "Logique & raisonnement", "Chaque nombre est le double du précédent : 40 × 2 = 80."),
("Quel nombre complète la suite : 1, 1, 2, 3, 5, 8, … ?", ["16","13","12","11"], "B", "Logique & raisonnement", "Chaque nombre est la somme des deux précédents : 5 + 8 = 13 (suite de Fibonacci)."),
("Tous les serveurs de la salle B sont sauvegardés. Le serveur X n'est pas sauvegardé. Que peut-on en conclure ?", ["On ne peut rien conclure","Le serveur X est dans la salle B","Le serveur X n'est pas dans la salle B","Tous les serveurs non sauvegardés sont dans la salle B"], "C", "Logique & raisonnement", "Si X était dans la salle B, il serait sauvegardé. Comme il ne l'est pas, il n'est pas dans la salle B."),
("« Si l'alarme sonne, alors la porte est ouverte. » La porte est ouverte. Que peut-on en conclure ?", ["On ne peut pas savoir si l'alarme sonne","L'alarme ne sonne pas","L'alarme sonne","La porte est fermée"], "A", "Logique & raisonnement", "La règle dit seulement ce qui se passe quand l'alarme sonne. La porte peut être ouverte pour une autre raison."),
("Le serveur A est plus rapide que le serveur B. Le serveur C est plus lent que le serveur A. Lequel est le plus lent ?", ["On ne peut pas savoir","Le serveur C","Le serveur B","Le serveur A"], "A", "Logique & raisonnement", "B et C sont tous les deux plus lents que A, mais rien ne permet de les comparer entre eux."),
("Combien de codes différents peut-on former avec 4 chiffres (de 0 à 9) ?", ["1 000","10 000","40","9 999"], "B", "Logique & raisonnement", "10 possibilités par position, 4 positions : 10 × 10 × 10 × 10 = 10 000 (de 0000 à 9999)."),
("Il est 22 h 45. Une sauvegarde dure 2 h 30. À quelle heure se termine-t-elle ?", ["0 h 15","1 h 45","1 h 15","24 h 75"], "C", "Logique & raisonnement", "22 h 45 + 2 h = 0 h 45 ; + 30 min = 1 h 15."),
("Un programme teste 1 000 codes par seconde. Combien de temps lui faut-il, au maximum, pour tester tous les codes à 4 chiffres ?", ["1 seconde","100 secondes","1 000 secondes","10 secondes"], "D", "Logique & raisonnement", "Il y a 10 000 codes : 10 000 ÷ 1 000 = 10 secondes. Un code à 4 chiffres ne résiste pas à une attaque automatisée."),
("Une sauvegarde de 120 Go est copiée à la vitesse de 2 Go par minute. Combien de temps dure la copie ?", ["1 heure","30 minutes","4 heures","2 heures"], "A", "Logique & raisonnement", "120 ÷ 2 = 60 minutes, soit 1 heure."),
("Sur 200 mails reçus, 15 % sont des spams. Combien de spams avez-vous reçus ?", ["30","45","20","15"], "A", "Logique & raisonnement", "15 % de 200 = 0,15 × 200 = 30."),
("Un technicien installe un poste en 15 minutes. Combien de postes trois techniciens installent-ils en 1 heure, au même rythme ?", ["12","9","4","45"], "A", "Logique & raisonnement", "Un technicien installe 4 postes par heure (60 ÷ 15) ; trois techniciens en installent 3 × 4 = 12."),
("Avec le chiffrement de César à décalage de 3, chaque lettre est remplacée par celle située 3 rangs plus loin (A devient D, B devient E…). Comment s'écrit le mot CHAT ?", ["DIBU","ZEXQ","FKDW","FKDV"], "C", "Logique & raisonnement", "C → F, H → K, A → D, T → W. DIBU correspond à un décalage de 1, ZEXQ à un décalage de 3 vers l'arrière."),
("Avec le même chiffrement de César (décalage de 3), quel mot se cache derrière le message chiffré FOH ?", ["BKD","CMF","CLE","ILK"], "C", "Logique & raisonnement", "Pour déchiffrer, on recule de 3 rangs : F → C, O → L, H → E."),
("Qu'affiche cet algorithme ?\nx ← 4\ny ← x × 2\nx ← y + 1\nAfficher x", ["8","9","4","5"], "B", "Algorithmique", "y vaut 8, puis x prend la valeur y + 1 = 9. L'ancienne valeur de x est remplacée."),
("Qu'affiche cet algorithme ?\ntotal ← 0\nPour i allant de 1 à 4 :\n    total ← total + i\nAfficher total", ["9","4","5","10"], "D", "Algorithmique", "La boucle additionne 1 + 2 + 3 + 4 = 10."),
("Qu'affiche cet algorithme ?\nprix ← 20\nSi prix > 15 alors\n    prix ← prix - 5\nAfficher prix", ["5","20","15","25"], "C", "Algorithmique", "20 est supérieur à 15 : la condition est vraie, on retire 5. prix vaut 15."),
("Qu'affiche cet algorithme ?\nâge ← 17\nSi âge ≥ 18 alors\n    Afficher \"majeur\"\nSinon\n    Afficher \"mineur\"", ["Rien","majeur","mineur","majeur puis mineur"], "C", "Algorithmique", "17 n'est pas supérieur ou égal à 18 : c'est la branche Sinon qui s'exécute."),
("Qu'affiche ce code Python ?\nmot = \"cyber\"\nprint(len(mot))", ["cyber","5","4","1"], "B", "Algorithmique", "len() renvoie le nombre de caractères de la chaîne : c, y, b, e, r, soit 5."),
("Qu'affiche cet algorithme ?\na ← 3\nb ← a + 2\nAfficher a + b", ["32","8","5","3"], "B", "Algorithmique", "b vaut 3 + 2 = 5, donc a + b = 3 + 5 = 8."),
("Qu'affiche ce code Python ?\nmdp = \"soleil\"\nif len(mdp) >= 8:\n    print(\"accepté\")\nelse:\n    print(\"trop court\")", ["accepté puis trop court","trop court","Une erreur","accepté"], "B", "Algorithmique", "« soleil » contient 6 caractères, moins que 8 : c'est la branche else qui s'exécute."),
("Qu'affiche ce code Python ?\nnom = \"Alice\"\nprint(\"Bonjour \" + nom)", ["Bonjour nom","Une erreur","nom Alice","Bonjour Alice"], "D", "Algorithmique", "La variable nom contient « Alice » ; le + colle les deux textes. Sans guillemets, nom désigne la variable, pas le mot."),
("Dans un programme, à quoi sert une boucle ?", ["À afficher une image","À répéter plusieurs fois des instructions","À connecter l'ordinateur à Internet","À stocker un mot de passe"], "B", "Algorithmique", "Une boucle (Pour, Tant que) répète un bloc d'instructions un nombre donné de fois ou tant qu'une condition est vraie."),
("Un accès est accordé si (badge valide ET code correct) OU si la personne est administrateur. Paul a un badge valide, un code faux, et n'est pas administrateur. Que se passe-t-il ?", ["L'accès est refusé","L'accès est accordé","L'accès est accordé seulement en journée","On ne peut pas savoir"], "A", "Algorithmique", "La parenthèse est fausse (le code est faux) et Paul n'est pas administrateur : les deux côtés du OU sont faux."),
("Que vaut le nombre binaire 1010 en décimal ?", ["10","1010","8","12"], "A", "Fonctionnement du numérique", "1010 = 1×8 + 0×4 + 1×2 + 0×1 = 10."),
("Quels sont les seuls chiffres utilisés en binaire ?", ["0 à 9","0, 1 et 2","0 et 1","1 et 2"], "C", "Fonctionnement du numérique", "Le binaire est la base 2 : toute information y est codée avec des 0 et des 1, ce qui correspond au courant qui passe ou ne passe pas."),
("Combien de bits contient un octet ?", ["2","1 000","10","8"], "D", "Fonctionnement du numérique", "Un octet est un groupe de 8 bits. C'est l'unité de base des tailles de fichiers (Ko, Mo, Go)."),
("À combien correspond 1 Go (gigaoctet) ?", ["1 000 Ko","1 000 Mo","1 000 To","100 Mo"], "B", "Fonctionnement du numérique", "Ko, Mo, Go, To : chaque unité vaut 1 000 fois la précédente (1 024 si l'on parle de Gio, de Mio…)."),
("Quel composant perd son contenu lorsqu'on éteint l'ordinateur ?", ["La clé USB","Le disque dur","La mémoire vive (RAM)","Le SSD"], "C", "Fonctionnement du numérique", "La RAM est une mémoire de travail temporaire ; le SSD, le disque dur et la clé USB conservent les données hors tension."),
("Cochez les éléments qui font partie du matériel (hardware) d'un ordinateur (plusieurs réponses possibles) :", ["Le système d'exploitation","La mémoire vive","La carte graphique","Le processeur"], "B,C,D", "Fonctionnement du numérique", "Le système d'exploitation est un logiciel (software). Les trois autres sont des composants physiques."),
("À quoi sert une adresse IP ?", ["À chiffrer les communications","À stocker les mots de passe","À identifier un appareil sur un réseau pour pouvoir lui envoyer des données","À mesurer la vitesse de la connexion"], "C", "Fonctionnement du numérique", "Comme une adresse postale, l'adresse IP permet d'acheminer les données vers le bon appareil."),
("Quel est le rôle principal d'une box Internet à la maison ?", ["Protéger l'ordinateur contre tous les virus","Remplacer le système d'exploitation","Relier les appareils du domicile à Internet","Stocker les photos de la famille"], "C", "Fonctionnement du numérique", "La box fait le lien entre le réseau de la maison (Wi-Fi, câble) et le réseau de l'opérateur. Elle ne remplace pas un antivirus."),
("Que signifie le cadenas affiché à côté de l'adresse d'un site web ?", ["Le site est officiel et sans danger","Le site a été vérifié par l'État","Le site ne contient pas de publicité","La connexion est chiffrée, mais le site peut quand même être frauduleux"], "D", "Fonctionnement du numérique", "Le cadenas indique une connexion HTTPS chiffrée. Les sites d'hameçonnage en ont aussi : il ne prouve pas que le site est honnête."),
("Que signifie « open source » pour un logiciel ?", ["Il est forcément gratuit","Il ne contient aucun virus","Il fonctionne sans connexion Internet","Son code source est accessible publiquement"], "D", "Fonctionnement du numérique", "Open source signifie que le code est consultable (et, selon la licence, modifiable). Cela ne garantit ni la gratuité ni l'absence de faille."),
("Vous recevez un SMS : « Votre colis est bloqué, réglez 1,99 € de frais ici » avec un lien vers laposte-livraison.info. Que faites-vous ?", ["Répondre pour demander plus d'informations","Payer, la somme est faible","Transférer le message à vos proches pour savoir s'ils l'ont aussi reçu","Ne pas cliquer et vérifier le suivi sur le site ou l'application officielle du transporteur"], "D", "Réflexes cyber", "C'est une arnaque classique : la petite somme sert à récupérer votre numéro de carte bancaire. Le nom de domaine n'est pas celui de La Poste."),
("Cochez les indices qui doivent faire penser à une arnaque dans un mail (plusieurs réponses possibles) :", ["Une adresse d'expéditeur qui ne correspond pas au site officiel","Une demande de coordonnées bancaires ou de mot de passe","Une urgence (« sous 24 h, sinon votre compte sera bloqué »)","La présence du logo de l'entreprise"], "A,B,C", "Réflexes cyber", "Un logo se copie en quelques secondes : sa présence ne prouve rien. L'urgence, l'expéditeur suspect et la demande d'informations sensibles sont des signaux d'alerte."),
("Lequel de ces mots de passe est le plus robuste ?", ["P@ssw0rd","cheval-lampe-orage-violon","Marie2008","Azerty123!"], "B", "Réflexes cyber", "La longueur compte plus que les symboles : une phrase de passe de plusieurs mots au hasard est longue et difficile à deviner. Les autres sont des modèles très courants, testés en premier par les attaquants."),
("Vous utilisez le même mot de passe sur tous vos sites. L'un d'eux se fait voler sa base de données. Quel est le risque ?", ["Votre mot de passe est changé automatiquement partout","Aucun, seul ce site est concerné","Votre ordinateur est automatiquement infecté","Les attaquants essaient ce mot de passe sur vos autres comptes (messagerie, réseaux sociaux…)"], "D", "Réflexes cyber", "La réutilisation des mots de passe permet de prendre le contrôle de tous vos comptes à partir d'une seule fuite."),
("À quoi sert la double authentification (code reçu par SMS ou dans une application) ?", ["À accélérer la connexion","À sauvegarder vos données","À remplacer l'antivirus","À empêcher la connexion de quelqu'un qui ne connaît que votre mot de passe"], "D", "Réflexes cyber", "Même si votre mot de passe fuit, l'attaquant doit aussi disposer de votre téléphone ou de votre application."),
("Dans un café, deux réseaux Wi-Fi apparaissent : « Cafe_Gratuit » et « Cafe-Gratuit-Free ». Quel est le risque ?", ["L'un des deux peut être un faux réseau créé par un pirate : il faut demander le nom exact au personnel","Le Wi-Fi va ralentir votre téléphone","Aucun, tous les Wi-Fi publics sont contrôlés","Les deux réseaux vont se brouiller"], "A", "Réflexes cyber", "Un pirate peut créer un point d'accès au nom proche pour piéger les connexions ou afficher de fausses pages de connexion."),
("Vous trouvez une clé USB dans un couloir de l'école. Que faites-vous ?", ["La remettre à l'accueil ou au service informatique, sans la brancher","La brancher pour retrouver son propriétaire","La formater sur votre ordinateur avant de la garder","La brancher sur un ordinateur de l'école plutôt que sur le vôtre"], "A", "Réflexes cyber", "Une clé piégée peut infecter l'ordinateur dès qu'elle est branchée. C'est une technique d'attaque connue."),
("Pourquoi faut-il installer rapidement les mises à jour de son téléphone ou de son ordinateur ?", ["Elles suppriment les publicités","Elles libèrent de l'espace de stockage","Elles corrigent des failles de sécurité que des pirates peuvent exploiter","Elles sont obligatoires par la loi"], "C", "Réflexes cyber", "Une fois une faille rendue publique, les attaquants l'exploitent vite sur les appareils non mis à jour."),
("Qu'est-ce qu'un rançongiciel (ransomware) ?", ["Un programme qui chiffre vos fichiers et exige un paiement pour les rendre","Un logiciel de sauvegarde payant","Un antivirus gratuit","Un programme qui affiche des publicités"], "A", "Réflexes cyber", "Le rançongiciel rend les fichiers illisibles et réclame une rançon. Les sauvegardes déconnectées sont la meilleure protection."),
("Laquelle de ces informations est une donnée personnelle ?", ["Le nombre d'habitants en France","La température à Paris aujourd'hui","Le prix d'un forfait mobile","Votre adresse e-mail"], "D", "Réflexes cyber", "Une donnée personnelle permet d'identifier une personne, directement ou indirectement. Les autres informations ne concernent personne en particulier."),
("Un site affiche : « Your password must contain at least 12 characters. » Que signifie ce message ?", ["Le mot de passe doit contenir au maximum 12 caractères","Le mot de passe doit contenir exactement 12 caractères","Le mot de passe doit contenir 12 chiffres","Le mot de passe doit contenir au moins 12 caractères"], "D", "Anglais", "« At least » signifie « au moins ». « At most » signifierait « au maximum »."),
("Un message affiche : « Access denied. Please contact your administrator. » Que signifie-t-il ?", ["Il faut redémarrer l'ordinateur","L'accès est refusé ; il faut contacter l'administrateur","L'accès est accordé par l'administrateur","Le compte administrateur a été supprimé"], "B", "Anglais", "« Access denied » = accès refusé ; « contact your administrator » = contactez votre administrateur."),
("Un SMS indique : « Do not share your verification code with anyone, including our staff. » Que faut-il comprendre ?", ["Le personnel va vous demander ce code","Ne partager le code avec personne, pas même avec le personnel de l'entreprise","Partager le code uniquement avec le personnel de l'entreprise","Le code peut être partagé avec sa famille"], "B", "Anglais", "« Including our staff » = y compris notre personnel. Un faux conseiller qui demande ce code est un signal d'arnaque."),
("Un message affiche : « The update will be installed when you restart your device. » Que signifie-t-il ?", ["La mise à jour a échoué","La mise à jour est déjà installée","L'appareil va redémarrer immédiatement","La mise à jour sera installée au redémarrage de l'appareil"], "D", "Anglais", "« Will be installed » = sera installée ; « when you restart » = quand vous redémarrerez."),
("Le navigateur affiche : « Warning: this file may harm your computer. Keep anyway? » Que signifie ce message ?", ["Le fichier a été supprimé ; voulez-vous le restaurer ?","Le fichier est trop volumineux ; voulez-vous le compresser ?","Le fichier pourrait endommager votre ordinateur ; voulez-vous quand même le conserver ?","Le fichier a été réparé ; voulez-vous l'ouvrir ?"], "C", "Anglais", "« May harm » = pourrait nuire ; « keep anyway » = conserver quand même. Dans le doute, on ne le conserve pas."),
]

# Énigmes inspirées de CYBEROKU (sudoku × CTF), ajoutées à la relecture
ENIGMES = [
("Énigme CYBEROKU. Dans cette grille, chaque ligne et chaque colonne contient une seule fois les chiffres 1, 2, 3 et 4.\n1 . 3 4\n. 4 . 2\n2 ? 4 .\n4 3 . 1\nQuel chiffre remplace le « ? » ?", ["1","2","3","4"], "A", "Énigmes CYBEROKU", "Sur sa ligne, il manque 1 et 3. Dans sa colonne, il y a déjà 4 et 3. Il ne reste que 1."),
("Énigme CYBEROKU. Dans cette grille, chaque ligne et chaque colonne contient une seule fois les symboles #, @ et $.\n# @ $\n@ $ #\n$ ? @\nQuel symbole remplace le « ? » ?", ["#","@","$","On ne peut pas savoir"], "A", "Énigmes CYBEROKU", "La ligne contient déjà $ et @, la colonne contient déjà @ et $ : il ne reste que #."),
("Énigme CYBEROKU. Un message est codé : chaque lettre est remplacée par son rang dans l'alphabet (A = 1, B = 2…). Que signifie 6 12 1 7 ?", ["FLAG","GLAG","FKAG","ELAG"], "A", "Énigmes CYBEROKU", "6 = F, 12 = L, 1 = A, 7 = G."),
("Énigme CYBEROKU. Un mot de passe est caché dans ce journal : prenez la première lettre de chaque ligne.\nPare-feu activé\nAccès refusé\nSession ouverte\nSauvegarde terminée\nQuel est le mot caché ?", ["PASS","PAOS","SAPS","PARS"], "A", "Énigmes CYBEROKU", "Les premières lettres des lignes donnent P, A, S, S."),
("Énigme CYBEROKU. Ana, Bilal et Chloé ont chacun trouvé un flag différent : web, réseau ou crypto. Ana n'a pas trouvé le flag web. Chloé a trouvé le flag crypto. Qui a trouvé le flag réseau ?", ["Ana","Bilal","Chloé","On ne peut pas savoir"], "A", "Énigmes CYBEROKU", "Chloé a crypto. Ana n'a pas web, donc elle a réseau, et Bilal a web."),
]
